export function organizeCarryForward(tasks, currentDay) {
  return tasks
    .filter((task) => !task.done && !task.canceled && !task.rescheduled)
    .map((task) => {
      const carriedFromFriday = currentDay === "Monday" && task.previousDay === "Friday";
      const group = task.waiting ? "waiting" : task.urgent || task.selected ? "must" : "other";
      return { ...task, group, carriedFromFriday };
    });
}

export function taskFromEmail(email) {
  if (!email.action || email.fyiOnly || email.newsletter) return null;
  return {
    id: `gmail-${email.threadId}`,
    title: email.action,
    project: email.project ?? null,
    meta: `${email.due ? `Due ${email.due} · ` : ""}Suggested from ${email.sender} · Review required`,
    group: "review",
    source: "Email",
    sourceUrl: email.sourceUrl,
    confidence: email.confidence,
    verifiedAt: email.verifiedAt,
  };
}

export function mergeEmailTask(tasks, incomingTask) {
  if (!incomingTask) return tasks;
  const existingIndex = tasks.findIndex((task) => task.id === incomingTask.id);
  if (existingIndex === -1) return [...tasks, incomingTask];
  return tasks.map((task, index) => (index === existingIndex ? { ...task, ...incomingTask } : task));
}

export function reviewEmailTask(task, decision, scheduledFor = null) {
  const groups = { addToday: "must", schedule: "scheduled", waiting: "waiting", ignore: "ignored" };
  if (!groups[decision]) throw new Error(`Unknown review decision: ${decision}`);
  return { ...task, group: groups[decision], reviewed: true, decision, scheduledFor };
}

export function applyTaskCorrection(task, title) {
  const correctedTitle = title.trim();
  if (!correctedTitle) throw new Error("A corrected task title is required");
  return { ...task, title: correctedTitle, corrected: true };
}

export function nextIdeaQuestion(answerCount) {
  return [
    "What would done look like for this idea?",
    "What have you completed already?",
    "What is still unfinished?",
    "Is there a deadline or preferred completion date?",
    "What is the smallest next action you could take?",
  ][answerCount] ?? null;
}

export function buildPilotTransfer(tasks, decisions, feedback, sourceSnapshot, availableMinutes) {
  return {
    version: 1,
    exportedAt: new Date().toISOString(),
    gmailCheckedAt: sourceSnapshot.gmail.checkedAt,
    calendarCheckedAt: sourceSnapshot.calendar.checkedAt,
    availableMinutes,
    tasks: tasks.map((task) => ({ id: task.id, title: task.title, project: task.project, meta: task.meta, sourceUrl: task.sourceUrl })),
    decisions,
    feedback,
  };
}

export function calculateCapacity(events, dayStart = 9, dayEnd = 17, transitionMinutes = 15) {
  const workStart = dayStart * 60;
  const workEnd = dayEnd * 60;
  const occupied = events
    .map((event) => {
      const start = new Date(event.start);
      const end = new Date(event.end);
      return {
        start: Math.max(workStart, start.getHours() * 60 + start.getMinutes() - transitionMinutes),
        end: Math.min(workEnd, end.getHours() * 60 + end.getMinutes() + transitionMinutes),
      };
    })
    .filter((range) => range.end > range.start)
    .sort((left, right) => left.start - right.start);

  const merged = [];
  for (const range of occupied) {
    const previous = merged.at(-1);
    if (previous && range.start <= previous.end) previous.end = Math.max(previous.end, range.end);
    else merged.push({ ...range });
  }
  const busyMinutes = merged.reduce((total, range) => total + range.end - range.start, 0);
  return { availableMinutes: (workEnd - workStart) - busyMinutes, busyMinutes, ranges: merged };
}

const decisionStorageKey = "work-activation-review-decisions-2026-08-06";
const feedbackStorageKey = "work-activation-feedback-2026-08-06";

function formatCheckedAt(value) {
  return new Intl.DateTimeFormat("en-CA", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value));
}

function escapeHtml(value) {
  return value.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" })[character]);
}

function loadDecisions() {
  try {
    return JSON.parse(localStorage.getItem(decisionStorageKey) ?? "{}");
  } catch {
    return {};
  }
}

function saveDecision(taskId, decision) {
  const decisions = loadDecisions();
  decisions[taskId] = decision;
  localStorage.setItem(decisionStorageKey, JSON.stringify(decisions));
}

function loadFeedback() {
  try {
    const stored = JSON.parse(localStorage.getItem(feedbackStorageKey) ?? "{}");
    return {
      corrections: stored.corrections ?? {},
      events: stored.events ?? [],
      ideas: stored.ideas ?? [],
    };
  } catch {
    return { corrections: {}, events: [], ideas: [] };
  }
}

function saveFeedback(feedback) {
  localStorage.setItem(feedbackStorageKey, JSON.stringify(feedback));
}

function recordFeedback(event) {
  const feedback = loadFeedback();
  feedback.events.unshift({ ...event, recordedAt: new Date().toISOString() });
  saveFeedback(feedback);
  renderFeedback();
}

function renderTask(task) {
  const row = document.createElement("div");
  row.className = "task";
  row.dataset.taskId = task.id;
  row.innerHTML = `
    <div class="task-main">
      <input type="checkbox" aria-label="Complete ${task.title}">
      <div>
        <div class="task-title"></div>
        <div class="task-meta"></div>
      </div>
    </div>
    <span class="tag">${task.source}</span>`;
  row.querySelector(".task-title").textContent = task.title;
  const meta = row.querySelector(".task-meta");
  meta.append(document.createTextNode(`${task.project ? `${task.project} · ` : ""}${task.meta} · `));
  const link = document.createElement("a");
  link.href = task.sourceUrl;
  link.target = "_blank";
  link.rel = "noreferrer";
  link.textContent = "Open source";
  meta.append(link);
  row.querySelector("input").addEventListener("change", (event) => row.classList.toggle("done", event.target.checked));
  return row;
}

function updateCounts() {
  const reviewCount = document.querySelectorAll("#review-list .task").length;
  const activeCount = document.querySelectorAll("#must-list .task").length;
  const waitingCount = document.querySelectorAll("#waiting-list .task").length;
  document.getElementById("review-count").textContent = reviewCount ? `${reviewCount} suggestions awaiting review` : "Review complete";
  document.getElementById("must-count").textContent = activeCount ? `${activeCount} approved for today` : "Nothing added until you approve it";
  document.getElementById("waiting-count").textContent = waitingCount ? `${waitingCount} approved waiting items` : "No reviewed waiting items";
}

function renderFeedback() {
  const feedback = loadFeedback();
  const list = document.getElementById("feedback-list");
  list.replaceChildren();
  const items = [
    ...feedback.events.map((event) => event.message),
    ...feedback.ideas.map((idea) => `Idea captured: ${idea.text}`),
  ];
  if (!items.length) {
    list.innerHTML = '<p class="empty-state">Corrections, decisions, and idea answers will appear here so you can see what the assistant learned.</p>';
    return;
  }
  for (const message of items.slice(0, 12)) {
    const item = document.createElement("div");
    item.className = "feedback-item";
    item.textContent = message;
    list.appendChild(item);
  }
}

function renderIdeas() {
  const feedback = loadFeedback();
  const list = document.getElementById("idea-list");
  list.replaceChildren();
  for (const idea of feedback.ideas) {
    const card = document.createElement("div");
    card.className = "idea-follow-up";
    const question = nextIdeaQuestion(idea.answers.length);
    const answerHistory = idea.answers.map((answer, index) => `<li><strong>${escapeHtml(nextIdeaQuestion(index))}</strong><br>${escapeHtml(answer)}</li>`).join("");
    card.innerHTML = `<strong class="idea-title"></strong>${answerHistory ? `<ol>${answerHistory}</ol>` : ""}`;
    card.querySelector(".idea-title").textContent = idea.text;
    if (question) {
      const prompt = document.createElement("p");
      prompt.className = "idea-question";
      prompt.textContent = question;
      const entry = document.createElement("div");
      entry.className = "idea-entry";
      entry.innerHTML = '<input aria-label="Idea follow-up answer"><button class="ghost">Save answer</button>';
      entry.querySelector("button").addEventListener("click", () => {
        const answer = entry.querySelector("input").value.trim();
        if (!answer) return;
        const current = loadFeedback();
        const stored = current.ideas.find((candidate) => candidate.id === idea.id);
        stored.answers.push(answer);
        current.events.unshift({ type: "idea-answer", message: `Idea updated: ${idea.text} — ${question} ${answer}`, recordedAt: new Date().toISOString() });
        saveFeedback(current);
        renderIdeas();
        renderFeedback();
      });
      card.append(prompt, entry);
    } else {
      const nextAction = document.createElement("p");
      nextAction.className = "idea-next-action";
      nextAction.textContent = `Next action: ${idea.answers.at(-1)}`;
      card.appendChild(nextAction);
    }
    list.appendChild(card);
  }
}

function renderReviewTask(task) {
  const row = renderTask(task);
  row.querySelector("input").remove();
  const content = row.querySelector(".task-main > div");
  const actions = document.createElement("div");
  actions.className = "review-actions";
  actions.innerHTML = `
    <button data-decision="addToday">Add today</button>
    <button data-decision="schedule">Schedule</button>
    <button data-decision="waiting">Waiting</button>
    <button data-decision="ignore">Ignore</button>
    <button data-feedback="correct">Correct wording</button>
    <button data-feedback="handled">Already handled</button>`;
  content.appendChild(actions);
  actions.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) return;
    if (button.dataset.feedback === "correct") {
      if (row.querySelector(".correction-entry")) return;
      const correction = document.createElement("div");
      correction.className = "idea-entry correction-entry";
      correction.innerHTML = '<input aria-label="Corrected task wording"><button class="ghost">Save correction</button>';
      correction.querySelector("input").value = task.title;
      correction.querySelector("button").addEventListener("click", () => {
        const corrected = applyTaskCorrection(task, correction.querySelector("input").value);
        task.title = corrected.title;
        row.querySelector(".task-title").textContent = corrected.title;
        const feedback = loadFeedback();
        feedback.corrections[task.id] = { title: corrected.title, correctedAt: new Date().toISOString() };
        saveFeedback(feedback);
        recordFeedback({ type: "correction", message: `Corrected ${task.project}: ${corrected.title}` });
        correction.remove();
      });
      content.appendChild(correction);
      correction.querySelector("input").focus();
      return;
    }
    if (button.dataset.feedback === "handled") {
      saveDecision(task.id, "ignore");
      recordFeedback({ type: "already-handled", message: `Already handled: ${task.title}` });
      row.remove();
      updateCounts();
      return;
    }
    const decision = button.dataset.decision;
    const reviewed = reviewEmailTask(task, decision);
    saveDecision(task.id, decision);
    recordFeedback({ type: "decision", message: `${button.textContent}: ${task.title}` });
    row.remove();
    if (reviewed.group === "must" || reviewed.group === "waiting") {
      document.getElementById(`${reviewed.group}-list`).appendChild(renderTask(reviewed));
    }
    updateCounts();
  });
  return row;
}

function renderCalendar() {
  const timeline = document.getElementById("timeline");
  for (const event of verifiedCalendarEvents) {
    const start = new Date(event.start);
    const end = new Date(event.end);
    const startMinutes = (start.getHours() - 9) * 60 + start.getMinutes();
    const duration = (end - start) / 60000;
    const block = document.createElement("a");
    block.className = "block meeting";
    block.style.top = `${startMinutes * (64 / 60)}px`;
    block.style.height = `${Math.max(34, duration * (64 / 60))}px`;
    block.href = event.sourceUrl;
    block.target = "_blank";
    block.rel = "noreferrer";
    block.textContent = `${start.toLocaleTimeString("en-CA", { hour: "numeric", minute: "2-digit" })} · ${event.title}`;
    block.title = event.private ? event.title : event.detail;
    timeline.appendChild(block);
  }
  const capacity = calculateCapacity(verifiedCalendarEvents);
  document.getElementById("capacity-value").textContent = `${Math.floor(capacity.availableMinutes / 60)}h ${capacity.availableMinutes % 60}m available`;
}

function render() {
  const decisions = loadDecisions();
  const feedback = loadFeedback();
  for (const originalTask of verifiedTasks) {
    const task = feedback.corrections[originalTask.id] ? { ...originalTask, title: feedback.corrections[originalTask.id].title } : { ...originalTask };
    const decision = decisions[task.id];
    if (!decision) document.getElementById("review-list").appendChild(renderReviewTask(task));
    else {
      const reviewed = reviewEmailTask(task, decision);
      if (reviewed.group === "must" || reviewed.group === "waiting") document.getElementById(`${reviewed.group}-list`).appendChild(renderTask(reviewed));
    }
  }

  document.getElementById("gmail-checked").textContent = formatCheckedAt(snapshot.gmail.checkedAt);
  document.getElementById("calendar-checked").textContent = formatCheckedAt(snapshot.calendar.checkedAt);
  document.getElementById("gmail-account").textContent = snapshot.gmail.account;
  updateCounts();
  renderCalendar();
  renderIdeas();
  renderFeedback();

  document.getElementById("transfer-to-noteplan").addEventListener("click", () => {
    const payload = buildPilotTransfer(verifiedTasks, loadDecisions(), loadFeedback(), snapshot, calculateCapacity(verifiedCalendarEvents).availableMinutes);
    const encoded = btoa(unescape(encodeURIComponent(JSON.stringify(payload))));
    const url = `noteplan://x-callback-url/runPlugin?pluginID=leslee.WorkActivationAssistant&command=${encodeURIComponent("Assistant: Import Pilot Review")}&arg0=${encodeURIComponent(encoded)}`;
    document.getElementById("connection-message").textContent = "Opening NotePlan and transferring your completed review…";
    window.location.href = url;
  });
  document.getElementById("reset-decisions")?.addEventListener("click", () => {
    localStorage.removeItem(decisionStorageKey);
    location.reload();
  });
  document.getElementById("reconnect-gmail")?.addEventListener("click", () => {
    document.getElementById("connection-message").textContent = "The production service will open Google OAuth here. This verified snapshot remains unchanged.";
  });
  document.getElementById("capture-idea")?.addEventListener("click", () => {
    const input = document.getElementById("idea-input");
    const response = document.getElementById("idea-response");
    if (!input.value.trim()) return;
    const feedback = loadFeedback();
    feedback.ideas.unshift({ id: `idea-${Date.now()}`, text: input.value.trim(), answers: [], createdAt: new Date().toISOString() });
    saveFeedback(feedback);
    response.hidden = false;
    response.textContent = `Saved: “${input.value.trim()}”. Answer the follow-up below; your answers will update this idea.`;
    input.value = "";
    renderIdeas();
    renderFeedback();
  });
  document.getElementById("clear-feedback")?.addEventListener("click", () => {
    localStorage.removeItem(feedbackStorageKey);
    location.reload();
  });
}

if (typeof document !== "undefined") render();
